fn solve(n: i8) -> Vec<char> {
    let n = n as usize;
    let mut result = Vec::with_capacity(n);
    // We use the repeating pattern "aabb".
    // For any i, (i % 4) < 2 -> 'a', else 'b'.
    // This guarantees s[i] != s[i+2] whenever i + 2 < n.
    for i in 0..n {
        let ch = if i % 4 < 2 { 'a' } else { 'b' };
        result.push(ch);
    }
    result
}

// -- Example Tests --

fn main() {
    // n = 1 -> ["a"]
    assert_eq!(solve(1), vec!['a']);
    // n = 2 -> ["a", "a"]
    // no distance-2 constraint to check
    assert_eq!(solve(2), vec!['a', 'a']);
    // n = 3 -> ["a", "a", "b"], check s[0]!=s[2] -> 'a'!='b'
    assert_eq!(solve(3), vec!['a', 'a', 'b']);
    // n = 5 -> ["a","a","b","b","a"], check s[0]!=s[2], s[1]!=s[3], s[2]!=s[4]
    assert_eq!(solve(5), vec!['a', 'a', 'b', 'b', 'a']);
    println!("All tests passed!");
}